def remaining_budget(context: int, prompt_tokens: int, output_reserve: int) -> int:
    if any(type(x) is not int for x in (context, prompt_tokens, output_reserve)):
        raise ValueError("integer counts required")
    if context <= 0 or prompt_tokens < 0 or output_reserve < 0:
        raise ValueError("invalid token counts")
    remaining = context - prompt_tokens - output_reserve
    if remaining < 0:
        raise ValueError("context exceeded")
    return remaining

import math
def scale_logits(logits: list[float], temperature: float) -> list[float]:
    if type(temperature) not in (int,float) or not math.isfinite(temperature) or temperature <= 0:
        raise ValueError("positive finite temperature required")
    if not logits or any(type(x) not in (int,float) or not math.isfinite(x) for x in logits):
        raise ValueError("finite logits required")
    return [x/temperature for x in logits]

import math
def top_k_ids(scores: list[float], k: int) -> list[int]:
    if type(k) is not int or k <= 0 or not scores:
        raise ValueError("nonempty scores and positive k required")
    if any(type(x) not in (int,float) or not math.isfinite(x) for x in scores):
        raise ValueError("finite scores required")
    return sorted(range(len(scores)),key=lambda i:(-scores[i],i))[:k]

import math
def nucleus_ids(probabilities: list[float], p: float) -> list[int]:
    if type(p) not in (int,float) or not math.isfinite(p) or not 0 < p <= 1:
        raise ValueError("invalid p")
    if not probabilities or any(type(x) not in (int,float) or not math.isfinite(x) or x < 0 for x in probabilities):
        raise ValueError("invalid probabilities")
    if not math.isclose(math.fsum(probabilities),1.0,rel_tol=0,abs_tol=1e-9):
        raise ValueError("probabilities must sum to one")
    chosen = []
    for i in sorted(range(len(probabilities)),key=lambda i:(-probabilities[i],i)):
        chosen.append(i)
        if math.fsum(probabilities[j] for j in chosen) + 1e-12 >= p:
            return chosen
    return chosen

import math
def greedy_id(logits: list[float]) -> int:
    if not logits or any(type(x) not in (int,float) or not math.isfinite(x) for x in logits):
        raise ValueError("finite nonempty logits required")
    return max(range(len(logits)),key=lambda i:logits[i])

def causal_mask(length: int) -> list[list[bool]]:
    if type(length) is not int or length < 0:
        raise ValueError("nonnegative length required")
    return [[j <= i for j in range(length)] for i in range(length)]

import math
def mix_values(weights: list[float], values: list[list[float]]) -> list[float]:
    if not weights or len(weights)!=len(values) or any(type(w) not in (int,float) or not math.isfinite(w) or w<0 for w in weights):
        raise ValueError("invalid weights")
    if not math.isclose(math.fsum(weights),1,rel_tol=0,abs_tol=1e-9):
        raise ValueError("weights must sum to one")
    width=len(values[0])
    if width==0 or any(len(row)!=width or any(type(x) not in (int,float) or not math.isfinite(x) for x in row) for row in values):
        raise ValueError("invalid value vectors")
    return [math.fsum(w*row[j] for w,row in zip(weights,values)) for j in range(width)]

def lookup_embeddings(token_ids: list[int], table: list[list[float]]) -> list[list[float]]:
    if any(type(i) is not int or not 0 <= i < len(table) for i in token_ids):
        raise ValueError("invalid vocabulary ID")
    return [list(table[i]) for i in token_ids]

import math
def attention_scores(query: list[float], keys: list[list[float]]) -> list[float]:
    if not query or any(type(x) not in (int,float) or not math.isfinite(x) for x in query):
        raise ValueError("invalid query")
    if any(len(k)!=len(query) or any(type(x) not in (int,float) or not math.isfinite(x) for x in k) for k in keys):
        raise ValueError("invalid keys")
    return [math.fsum(a*b for a,b in zip(query,k))/math.sqrt(len(query)) for k in keys]

import math
def residual_add(state: list[float], update: list[float]) -> list[float]:
    if len(state)!=len(update) or any(type(x) not in (int,float) or not math.isfinite(x) for x in state+update):
        raise ValueError("matching finite vectors required")
    return [x+y for x,y in zip(state,update)]

