import hashlib
def prompt_sha256(prompt: str) -> str:
    if not isinstance(prompt,str):
        raise TypeError("prompt must be str")
    return hashlib.sha256(prompt.encode("utf-8")).hexdigest()

import math
def valid_baseline(settings: dict[str, object]) -> bool:
    if not isinstance(settings,dict):
        return False
    def number(x):
        return type(x) is int or (type(x) is float and math.isfinite(x))
    c=settings.get("context_size");o=settings.get("max_output_tokens")
    t=settings.get("temperature");k=settings.get("top_k")
    p=settings.get("top_p");timeout=settings.get("timeout_seconds")
    return (type(c) is int and c==4096 and type(o) is int and o==512
        and settings.get("stream") is False and number(t) and 0<=t<=2
        and type(k) is int and k>=0 and number(p) and 0<p<=1
        and number(timeout) and 0<timeout<=3600)

