import re
def allowed_origin(url: str) -> bool:
    if not isinstance(url,str):
        return False
    match=re.fullmatch(r"http://127\.0\.0\.1:([0-9]{1,5})",url)
    return match is not None and 1<=int(match.group(1))<=65535

def token_metric(value: object) -> dict[str, object]:
    valid=type(value) is int and value>=0
    return {"value":value if valid else None,"unit":"tokens",
            "unavailable_reason":None if valid else "not a non-negative integer"}

def completion_text(payload: object, expected_model: str) -> str:
    if not isinstance(expected_model,str) or not expected_model or not isinstance(payload,dict) or payload.get("model")!=expected_model:
        raise ValueError("identity mismatch")
    choices=payload.get("choices")
    if not isinstance(choices,list) or len(choices)!=1 or not isinstance(choices[0],dict):
        raise ValueError("invalid choices")
    message=choices[0].get("message")
    if not isinstance(message,dict) or not isinstance(message.get("content"),str):
        raise ValueError("invalid content")
    return message["content"]

