def trial_schedule(case_ids: list[str]) -> list[tuple[str,int]]:
    if any(not isinstance(c,str) or not c.strip() for c in case_ids) or len(set(case_ids))!=len(case_ids):
        raise ValueError("unique nonblank case IDs required")
    return [(case_id,number) for case_id in case_ids for number in (1,2,3)]

from copy import deepcopy
def add_record(records: list[dict], record: dict) -> list[dict]:
    for existing in records:
        if existing["id"]==record["id"]:
            if existing!=record:
                raise ValueError("record identity conflict")
            return deepcopy(records)
    return deepcopy([*records,record])

def criterion_total(scores: list[int | None]) -> tuple[int,int]:
    if any(s is not None and (type(s) is not int or s not in (0,1,2)) for s in scores):
        raise ValueError("invalid rubric score")
    applicable=[s for s in scores if s is not None]
    return sum(applicable),2*len(applicable)
